MagickExport MagickBooleanType SyncCacheViewAuthenticPixels( /* <=== SyncCacheViewAuthenticPixels */ 
  CacheView *magick_restrict cache_view,ExceptionInfo *exception)
{
  const int
    id = GetOpenMPThreadId();

  MagickBooleanType
